mapper.select:
select * from experience_post
where id in

    #{id}

select ep.id, ep.user_id as userId, u.name as userName, u.avatar as userAvatar, ep.content, ep.product_type as productType, ep.product_id as productId, ep.images, ep.like_count as likeCount, ep.comment_count as commentCount, ep.hidden, ep.create_time as createTime, ep.update_time as updateTime from experience_post ep left join user u on ep.user_id = u.id
and ep.product_type = #{productType}
and ep.product_id = #{productId}
and ep.hidden = #{hidden}
order by ep.create_time desc

select ep.id, ep.user_id as userId, u.name as userName, u.avatar as userAvatar, SUBSTRING(ep.content, 1, 100) as contentSummary, ep.content, ep.product_type as productType, CASE ep.product_type WHEN 1 THEN '鞋款' WHEN 2 THEN '组合包' WHEN 3 THEN '抽签' WHEN 4 THEN '空投' ELSE '未知' END as productTypeName, ep.product_id as productId, CASE ep.product_type WHEN 1 THEN shoe.name WHEN 2 THEN bundle.name WHEN 3 THEN draw.title WHEN 4 THEN airdrop.title END as productName, CASE ep.product_type WHEN 1 THEN (SELECT sku.image FROM shoe_sku sku WHERE sku.spu_id = shoe.id ORDER BY sku.is_default DESC, sku.id ASC LIMIT 1) WHEN 2 THEN bundle.image WHEN 3 THEN NULL WHEN 4 THEN NULL END as productImage, ep.images, ep.like_count as likeCount, ep.comment_count as commentCount, ep.hidden, ep.create_time as createTime, ep.update_time as updateTime from experience_post ep left join user u on ep.user_id = u.id left join shoe_spu shoe on ep.product_type = 1 and ep.product_id = shoe.id left join bundle bundle on ep.product_type = 2 and ep.product_id = bundle.id left join draw draw on ep.product_type = 3 and ep.product_id = draw.id left join airdrop airdrop on ep.product_type = 4 and ep.product_id = airdrop.id
and u.name like concat('%', #{dto.userName}, '%')
and ep.content like concat('%', #{dto.contentKeyword}, '%')
and ep.product_type = #{dto.productType}
and ( (ep.product_type = 1 and shoe.name like concat('%', #{dto.productName}, '%')) or (ep.product_type = 2 and bundle.name like concat('%', #{dto.productName}, '%')) or (ep.product_type = 3 and draw.title like concat('%', #{dto.productName}, '%')) or (ep.product_type = 4 and airdrop.title like concat('%', #{dto.productName}, '%')) )
and ep.create_time >= #{dto.startTime}
and ep.create_time <= #{dto.endTime}
and ep.hidden = #{dto.hidden}
order by ep.create_time desc

mapper.update:
update experience_post
set content = #{content},
    images = #{images},
    update_time = #{updateTime}
where id = #{id}
